/* === DESIGN TOKENS === */
:root {
  --ink: #161922;
  --paper: #f6efe2;
  --paper-2: #fffaf0;
  --slate: #263447;
  --muted: #6d756f;
  --teal: #0f8f8c;
  --teal-dark: #096c6d;
  --coral: #d95f4a;
  --gold: #d7a53a;
  --lavender: #7061a8;
  --line: rgba(38, 52, 71, 0.18);
  --shadow: 0 clamp(0.75rem, 2vw, 1.5rem) clamp(2rem, 5vw, 4rem) rgba(22, 25, 34, 0.15);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

/* === GLOBAL PRESENTATION FRAME === */
* { box-sizing: border-box; }
body {
  margin: 0;
  color: var(--ink);
  font-family: "IBM Plex Sans", sans-serif;
  background: var(--paper);
}
.slide {
  background:
    radial-gradient(circle at 8% 12%, rgba(215, 165, 58, 0.20), transparent 28%),
    radial-gradient(circle at 92% 8%, rgba(15, 143, 140, 0.14), transparent 30%),
    linear-gradient(135deg, var(--paper-2), var(--paper));
}
.slide::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(38,52,71,0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(38,52,71,0.035) 1px, transparent 1px);
  background-size: clamp(1.5rem, 3vw, 3rem) clamp(1.5rem, 3vw, 3rem);
  mask-image: linear-gradient(to bottom, rgba(0,0,0,0.8), rgba(0,0,0,0.2));
  pointer-events: none;
}
.slide::after {
  content: "";
  position: absolute;
  inset: clamp(0.8rem, 1.5vw, 1.25rem);
  border: clamp(0.05rem, 0.1vw, 0.08rem) solid var(--line);
  pointer-events: none;
}
.slide-content { z-index: 1; gap: var(--content-gap); }

/* === TYPOGRAPHY === */
h1, h2, h3, p { margin: 0; }
h1, h2, .number, .mega-number {
  font-family: "Fraunces", serif;
  letter-spacing: -0.045em;
}
h1 { font-size: clamp(2.2rem, 6.2vw, 5.8rem); line-height: 0.92; max-width: min(88vw, 68rem); }
h2 { font-size: clamp(1.7rem, 4.3vw, 4rem); line-height: 0.98; max-width: min(88vw, 62rem); }
h3 { font-size: var(--h3-size); line-height: 1.1; font-weight: 700; }
p, li { font-size: var(--body-size); line-height: 1.45; }
.eyebrow {
  font-size: clamp(0.68rem, 1.1vw, 0.95rem);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--teal-dark);
  font-weight: 700;
}
.subtitle { max-width: min(75vw, 48rem); color: var(--slate); font-size: clamp(1rem, 1.9vw, 1.45rem); }
.source { color: var(--muted); font-size: var(--small-size); }
.kicker { color: var(--coral); font-weight: 700; }

/* === REVEAL ANIMATIONS === */
.reveal {
  opacity: 0;
  transform: translateY(clamp(0.8rem, 2vw, 1.8rem));
  transition: opacity 0.65s var(--ease-out-expo), transform 0.65s var(--ease-out-expo);
}
.visible .reveal { opacity: 1; transform: translateY(0); }
.reveal:nth-child(2) { transition-delay: 0.08s; }
.reveal:nth-child(3) { transition-delay: 0.16s; }
.reveal:nth-child(4) { transition-delay: 0.24s; }
.reveal:nth-child(5) { transition-delay: 0.32s; }

/* === SHARED LAYOUTS === */
.two-col {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: clamp(1rem, 3vw, 3rem);
  align-items: center;
  width: min(100%, 76rem);
}
.stack { display: flex; flex-direction: column; gap: clamp(0.7rem, 1.5vw, 1.35rem); }
.panel {
  background: rgba(255, 250, 240, 0.82);
  border: clamp(0.05rem, 0.1vw, 0.08rem) solid var(--line);
  border-radius: clamp(1rem, 2vw, 1.75rem);
  box-shadow: var(--shadow);
  padding: clamp(1rem, 2.2vw, 2rem);
  backdrop-filter: blur(clamp(0.4rem, 1vw, 0.8rem));
}
.pill {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: clamp(0.35rem, 0.7vw, 0.55rem) clamp(0.65rem, 1.1vw, 1rem);
  border-radius: 999rem;
  border: clamp(0.05rem, 0.1vw, 0.08rem) solid var(--line);
  color: var(--slate);
  background: rgba(255,255,255,0.45);
  font-weight: 700;
  font-size: var(--small-size);
}
.note { color: var(--muted); font-size: clamp(0.78rem, 1.15vw, 1rem); }

/* === TITLE SLIDE === */
.title-slide .slide-content { justify-content: space-between; }
.title-grid {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: clamp(1rem, 3vw, 3rem);
  align-items: end;
}
.seal {
  width: clamp(7rem, 16vw, 15rem);
  aspect-ratio: 1;
  border-radius: 50%;
  background: conic-gradient(from 210deg, var(--teal), var(--gold), var(--coral), var(--teal));
  padding: clamp(0.45rem, 0.9vw, 0.8rem);
  box-shadow: var(--shadow);
}
.seal-inner {
  height: 100%;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--paper-2);
  text-align: center;
  font-weight: 800;
  color: var(--slate);
  font-size: clamp(0.75rem, 1.5vw, 1.25rem);
}
.footer-row { display: flex; justify-content: space-between; gap: var(--content-gap); align-items: end; }

/* === PREVALENCE SLIDE === */
.callout-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(0.8rem, 2vw, 1.6rem);
}
.callout {
  min-height: clamp(12rem, 34vh, 22rem);
  border-radius: clamp(1rem, 2vw, 1.75rem);
  padding: clamp(1rem, 2.4vw, 2.2rem);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: var(--paper-2);
  box-shadow: var(--shadow);
  position: relative;
  overflow: hidden;
}
.callout::after {
  content: "";
  position: absolute;
  width: clamp(7rem, 15vw, 14rem);
  aspect-ratio: 1;
  border-radius: 50%;
  right: calc(-1 * clamp(2rem, 4vw, 4rem));
  bottom: calc(-1 * clamp(2rem, 4vw, 4rem));
  background: rgba(255,255,255,0.12);
}
.callout.women { background: linear-gradient(135deg, #b54e62, var(--coral)); }
.callout.men { background: linear-gradient(135deg, var(--teal-dark), var(--teal)); }
.mega-number { font-size: clamp(3.4rem, 10vw, 9rem); line-height: 0.9; }
.callout-label { font-weight: 700; font-size: clamp(1rem, 2vw, 1.5rem); max-width: 16rem; }

/* === BAR CHARTS === */
.chart-panel { width: min(100%, 74rem); }
.bars { display: flex; flex-direction: column; gap: clamp(0.55rem, 1.2vh, 0.9rem); }
.bar-row {
  display: grid;
  grid-template-columns: clamp(8rem, 19vw, 16rem) 1fr clamp(4rem, 7vw, 5.5rem);
  gap: clamp(0.5rem, 1.1vw, 1rem);
  align-items: center;
}
.label { font-weight: 700; color: var(--slate); font-size: clamp(0.78rem, 1.35vw, 1.05rem); }
.track {
  height: clamp(1.25rem, 4.5vh, 3.3rem);
  border-radius: 999rem;
  background: rgba(38,52,71,0.08);
  overflow: hidden;
  border: clamp(0.05rem, 0.1vw, 0.08rem) solid rgba(38,52,71,0.10);
}
.fill {
  height: 100%;
  width: var(--w);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--teal), var(--gold));
  box-shadow: inset 0 0 clamp(0.8rem, 2vw, 1.5rem) rgba(255,255,255,0.28);
}
.value { font-weight: 800; color: var(--ink); font-size: clamp(0.78rem, 1.3vw, 1.05rem); text-align: right; }
.axis-note { display: flex; justify-content: space-between; margin-top: clamp(0.5rem, 1vw, 0.9rem); color: var(--muted); font-size: var(--small-size); }

/* === PARITY SLIDE === */
.paired {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(0.8rem, 2vw, 1.6rem);
  width: min(100%, 58rem);
}
.tower {
  min-height: clamp(18rem, 48vh, 30rem);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: clamp(0.5rem, 1vw, 0.8rem);
}
.tower-bar {
  border-radius: clamp(1rem, 1.8vw, 1.5rem) clamp(1rem, 1.8vw, 1.5rem) clamp(0.25rem, 0.7vw, 0.6rem) clamp(0.25rem, 0.7vw, 0.6rem);
  min-height: var(--h);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(0.8rem, 1.6vw, 1.3rem);
  color: white;
  font-weight: 800;
  font-size: clamp(1.5rem, 3.3vw, 3.2rem);
  box-shadow: var(--shadow);
}
.tower.dep .tower-bar { background: linear-gradient(180deg, var(--coral), #9b3c42); }
.tower.anx .tower-bar { background: linear-gradient(180deg, var(--teal), var(--teal-dark)); }
.parity-badge {
  position: absolute;
  right: clamp(3rem, 7vw, 7rem);
  top: clamp(8rem, 18vh, 12rem);
  transform: rotate(3deg);
  background: var(--ink);
  color: var(--paper-2);
  padding: clamp(0.65rem, 1.2vw, 1rem) clamp(0.9rem, 1.8vw, 1.4rem);
  border-radius: clamp(0.8rem, 1.5vw, 1.2rem);
  font-weight: 800;
  box-shadow: var(--shadow);
}

/* === SEVERE CONDITIONS === */
.compare-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: clamp(1rem, 3vw, 2.5rem);
  width: min(100%, 74rem);
  align-items: center;
}
.mini-bars { display: flex; flex-direction: column; gap: clamp(0.8rem, 1.4vh, 1.2rem); }
.severity-card {
  border-left: clamp(0.25rem, 0.5vw, 0.45rem) solid var(--coral);
}

/* === TREATMENT GAP === */
.infographic {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(0.6rem, 1.5vw, 1.2rem);
  width: min(100%, 74rem);
}
.icon-card {
  min-height: clamp(12rem, 30vh, 18rem);
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(0.5rem, 1vw, 0.9rem);
}
.icon {
  width: clamp(3rem, 6vw, 5.2rem);
  aspect-ratio: 1;
  margin: 0 auto;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: white;
  font-size: clamp(1.5rem, 3vw, 2.7rem);
  background: var(--teal-dark);
}
.icon-card:nth-child(2) .icon { background: var(--coral); }
.icon-card:nth-child(3) .icon { background: var(--gold); color: var(--ink); }
.icon-card:nth-child(4) .icon { background: var(--lavender); }

/* === COPING === */
.coping-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.8rem, 2vw, 1.6rem);
  width: min(100%, 72rem);
}
.coping-card {
  min-height: clamp(14rem, 34vh, 22rem);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.coping-icon { font-size: clamp(2.2rem, 5vw, 4rem); }
.region-line {
  height: clamp(0.35rem, 0.8vw, 0.55rem);
  border-radius: 999rem;
  background: linear-gradient(90deg, var(--teal), var(--gold), var(--coral));
}

/* === TAKEAWAYS === */
.takeaways {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(0.7rem, 1.6vw, 1.25rem);
  width: min(100%, 76rem);
}
.takeaway {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: clamp(0.6rem, 1.2vw, 1rem);
  align-items: start;
}
.num {
  font-family: "Fraunces", serif;
  font-size: clamp(1.4rem, 3vw, 2.7rem);
  color: var(--teal-dark);
  line-height: 0.9;
}

/* === NAVIGATION HELPERS === */
.nav-dots {
  position: fixed;
  right: clamp(0.8rem, 1.5vw, 1.2rem);
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: clamp(0.35rem, 0.7vw, 0.55rem);
  z-index: 10;
}
.nav-dots button {
  width: clamp(0.45rem, 0.8vw, 0.7rem);
  height: clamp(0.45rem, 0.8vw, 0.7rem);
  border: 0;
  border-radius: 50%;
  background: rgba(38,52,71,0.25);
  padding: 0;
}
.nav-dots button.active { background: var(--coral); }
.keyboard-hint {
  position: fixed;
  left: clamp(1rem, 2vw, 1.5rem);
  bottom: clamp(0.8rem, 1.5vw, 1.2rem);
  z-index: 10;
  color: rgba(38,52,71,0.55);
  font-size: var(--small-size);
}

/* === RESPONSIVE CUSTOM OVERRIDES === */
@media (max-width: 900px) {
  .two-col, .compare-grid, .title-grid { grid-template-columns: 1fr; }
  .infographic, .coping-grid, .takeaways { grid-template-columns: 1fr 1fr; }
  .seal { display: none; }
}
@media (max-width: 600px), (max-height: 650px) {
  .infographic, .coping-grid, .takeaways, .callout-grid, .paired { grid-template-columns: 1fr; }
  .icon-card, .coping-card { min-height: auto; }
  .parity-badge { display: none; }
}
