  <script>
/* === SLIDE NAVIGATION AND REVEAL CONTROL === */
const slides = Array.from(document.querySelectorAll('.slide'));
const dots = document.querySelector('.nav-dots');
let current = 0;

slides.forEach((slide, index) => {
  const button = document.createElement('button');
  button.setAttribute('aria-label', `Go to slide ${index + 1}`);
  button.addEventListener('click', () => goTo(index));
  dots.appendChild(button);
});

function setActive(index) {
  current = Math.max(0, Math.min(slides.length - 1, index));
  slides.forEach((slide, slideIndex) => slide.classList.toggle('visible', slideIndex === current));
  Array.from(dots.children).forEach((dot, dotIndex) => dot.classList.toggle('active', dotIndex === current));
}

function goTo(index) {
  setActive(index);
  slides[current].scrollIntoView({ behavior: 'smooth', block: 'start' });
}

document.addEventListener('keydown', (event) => {
  if (['ArrowRight', 'ArrowDown', ' ', 'PageDown'].includes(event.key)) {
    event.preventDefault();
    goTo(current + 1);
  }
  if (['ArrowLeft', 'ArrowUp', 'PageUp'].includes(event.key)) {
    event.preventDefault();
    goTo(current - 1);
  }
});

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) setActive(slides.indexOf(entry.target));
  });
}, { threshold: 0.65 });
slides.forEach((slide) => observer.observe(slide));
setActive(0);
  </script>
</body>
